// A native-language exam (ExamConfig.language) is listed by its English name
// (ExamConfig.english) everywhere but its own country's homepage.
const examEntry = (exam: ExamConfig): TestCatalogEntry => ({
  id: exam.id,
  shortName: examEnglishName(exam).shortName,
  name: examEnglishName(exam).name,
  org: EXAM_ORG[exam.id] ?? exam.examLabel,
  blurb: EXAM_BLURBS[exam.id] ?? examEnglishName(exam).fullName,
  href: examLandingPath(exam),
  dashboardHref: `${exam.slug}/dashboard`,
  questions: (EXAM_BANK_SIZES as Record<string, number>)[exam.id] ?? exam.testCount * exam.questionsPerTest,
  icon: exam.icon,
  theme: exam.id,
  languages: examLanguages(exam),
  ...(examBaseLanguage(exam) !== "en"
    ? { language: examBaseLanguage(exam), nativeName: exam.name, nativeShortName: exam.shortName }
    : {}),
});

// v2 exams (sectioned, timed, scaled scores) live outside the v1 registry.
const v2Entry = (exam: ExamV2Config): TestCatalogEntry => ({
  id: exam.id,
  shortName: exam.english?.shortName ?? exam.shortName,
  name: exam.english?.name ?? exam.name,
  org: EXAM_ORG[exam.id] ?? exam.fullName,
  blurb: EXAM_BLURBS[exam.id] ?? exam.tagline,
  href: exam.landingPath,
  dashboardHref: `${exam.slug}/dashboard`,
  questions: BANK_SIZES[exam.id] ?? 0,
  icon: exam.icon as TestCatalogEntry["icon"],
  theme: exam.id,
  languages: [exam.language ?? "en"],
  ...(exam.language && exam.language !== "en"
    ? { language: exam.language, nativeName: exam.name, nativeShortName: exam.shortName }
    : {}),
  // Exams with a Premium tier say so on their hub card; the rest read "Free".
  ...(exam.premium
    ? { pricing: `${exam.tests.length - exam.premium.lockedTests.length} free, ${exam.premium.lockedTests.length} premium` }
    : {}),
});

export const TEST_CATALOG: TestCatalogEntry[] = [dmv, ...EXAMS_V2.map(v2Entry), ...EXAMS.map(examEntry)];

